import{_ as e,o as i,c as t,a0 as o}from"./chunks/framework.Bmhw_dvp.js";const b=JSON.parse('{"title":"常见问题","description":"","frontmatter":{},"headers":[],"relativePath":"basic/faq.md","filePath":"basic/faq.md","lastUpdated":1793354613000}'),s={name:"basic/faq.md"};function r(d,a,l,c,n,h){return i(),t("div",null,[...a[0]||(a[0]=[o(`<h1 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h1><h2 id="自签证书提示不受信任" tabindex="-1">自签证书提示不受信任 <a class="header-anchor" href="#自签证书提示不受信任" aria-label="Permalink to &quot;自签证书提示不受信任&quot;">​</a></h2><p><code>localhost</code> 与公网 IP 使用自签证书时，浏览器会提示颁发机构不受信任。处理方式：把 <code>config/ssl/cert.pem</code> 导入客户端「受信任的根证书颁发机构」，或改用域名走 Let&#39;s Encrypt，见 <a href="/advanced/https">HTTPS 证书</a>。</p><h2 id="websocket-连接失败" tabindex="-1">WebSocket 连接失败 <a class="header-anchor" href="#websocket-连接失败" aria-label="Permalink to &quot;WebSocket 连接失败&quot;">​</a></h2><p>确认反向代理已配置 WebSocket 升级头：</p><div class="language-nginx vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">nginx</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">proxy_http_version </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1.1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">proxy_set_header </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Upgrade $http_upgrade;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">proxy_set_header </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Connection </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;upgrade&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><h2 id="语音聊天连不上" tabindex="-1">语音聊天连不上 <a class="header-anchor" href="#语音聊天连不上" aria-label="Permalink to &quot;语音聊天连不上&quot;">​</a></h2><p>语音媒体默认走 <code>3333/udp</code>，服务器防火墙需放行；同时放行 <code>3337/tcp</code> 可让 UDP 被拦的客户端改走直连。仍不通时可配置 TURN/TLS 中继（<code>3338/tcp</code>）兜底，见<a href="/advanced/env">环境变量</a>中的 <code>LIVEKIT_TURN_*</code> 三项。</p><h2 id="webrtc-无法建立连接" tabindex="-1">WebRTC 无法建立连接 <a class="header-anchor" href="#webrtc-无法建立连接" aria-label="Permalink to &quot;WebRTC 无法建立连接&quot;">​</a></h2><p><code>getUserMedia</code> 要求 HTTPS 访问，生产环境需配置 SSL 证书。</p><h2 id="数据库" tabindex="-1">数据库 <a class="header-anchor" href="#数据库" aria-label="Permalink to &quot;数据库&quot;">​</a></h2><p>后端用 Go 的纯 Go SQLite 驱动持久化，标准 SQLite 格式（<code>config/dev.sqlite</code>），可用常规工具查看；WAL 模式下同目录还会有 <code>-wal</code> / <code>-shm</code> 旁文件，属正常现象，别手删。</p><p>备份用 <code>npm run db:backup -- &lt;目标路径&gt;</code>（内部 <code>VACUUM INTO</code>），直接 <code>cp</code> 主文件会丢最近事务。只有 SQLite，不支持 PostgreSQL。</p><h2 id="bilibili-解析失败" tabindex="-1">Bilibili 解析失败 <a class="header-anchor" href="#bilibili-解析失败" aria-label="Permalink to &quot;Bilibili 解析失败&quot;">​</a></h2><ul><li>确认后端正确携带 Referer 等请求头（封面与视频地址经后端代理，规避 CORS 与防盗链）。</li><li>大会员内容需配置有效的 Bilibili 登录凭证，或使用 <a href="/basic/cli">ZViewer CLI 本地代理</a>。</li></ul><h2 id="房主离线后房间会怎样" tabindex="-1">房主离线后房间会怎样 <a class="header-anchor" href="#房主离线后房间会怎样" aria-label="Permalink to &quot;房主离线后房间会怎样&quot;">​</a></h2><p>服务器继续广播当前播放状态，观众不中断；离线超时 10 分钟自动关房，期间观众可自主控制。</p><h2 id="如何修改默认-root-密码" tabindex="-1">如何修改默认 root 密码 <a class="header-anchor" href="#如何修改默认-root-密码" aria-label="Permalink to &quot;如何修改默认 root 密码&quot;">​</a></h2><p>用 <code>root</code> / <code>root</code> 登录后进入个人资料页修改；管理员也可在后台用户管理中处理。</p><h2 id="更新机制" tabindex="-1">更新机制 <a class="header-anchor" href="#更新机制" aria-label="Permalink to &quot;更新机制&quot;">​</a></h2><p>默认从 GitCode 镜像（国内直连）检查并一键更新，也可在后台关掉镜像改走 GitHub Releases，或手动上传压缩包。管理员可控制是否接收预发布版，见<a href="/advanced/build-update">构建与更新</a>。</p>`,21)])])}const k=e(s,[["render",r]]);export{b as __pageData,k as default};
